package org.dromara.sports.event.service;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.sports.api.OrganizationSessionApi;
import org.dromara.sports.api.OrganizationQualificationApi;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;
@Service @RequiredArgsConstructor
public class EventClosureService implements CapabilityProvider {
 private final ScopedJdbc db;private final ObjectMapper json;private final OrganizationSessionApi organizations;private final OrganizationQualificationApi qualifications;
 private static final Set<String> READS=Set.of("asp_event","asp_competition_unit","asp_registration","asp_fee_obligation","asp_payment_action","asp_payment_exception","asp_refund","asp_payment_allocation","asp_payment","asp_complaint","asp_match","asp_stage","asp_result_version","asp_honor");
 public List<CapabilityDefinition> capabilities(){return List.of(capability(json,"event.closure","检查比赛、资金与问题收尾","asp_event",true,false,Set.of("organizer"),"",READS,Set.of(),"eventId"),capability(json,"event.wrapup","确认比赛结束并进入收尾","asp_event",false,true,Set.of("organizer"),"",READS,Set.of("asp_event"),"eventId","expectedVersion"),capability(json,"event.close","确认赛事所有待办已收尾","asp_event",false,true,Set.of("organizer"),"",READS,Set.of("asp_event"),"eventId","expectedVersion"));}
 private Map<String,Object> owned(long event){var o=organizations.managedOrganization(BusinessIdentity.getUserId()).orElseThrow(()->fail("请进入主办方工作台",403));if(!qualifications.hasStaffAction(o.tenantId(),o.organizationId(),o.accountId(),"organize"))throw fail("当前岗位没有赛事办理权限",403);var e=db.one("SELECT id,name,holding_status,closure_status,version,starts_at,(starts_at IS NOT NULL AND starts_at<=CURRENT_TIMESTAMP) AS has_started FROM asp_event WHERE id=? AND tenant_id=? AND organization_id=?",event,o.tenantId(),o.organizationId());if(e==null)throw fail("赛事不在当前组织范围",403);return e;}
 public JsonNode preview(String code,JsonNode in){return summary(id(in,"eventId"));}
 public JsonNode summary(long event){var e=owned(event);var n=json.createObjectNode();n.set("event",safeJson(json,e));long matches=db.count("SELECT count(*) FROM asp_match m JOIN asp_stage s ON s.id=m.stage_id JOIN asp_competition_unit u ON u.id=s.unit_id WHERE u.event_id=? AND m.status<>'cancelled'",event);long unsettled=db.count("SELECT count(*) FROM asp_match m JOIN asp_stage s ON s.id=m.stage_id JOIN asp_competition_unit u ON u.id=s.unit_id WHERE u.event_id=? AND m.status<>'cancelled' AND NOT EXISTS(SELECT 1 FROM asp_result_version v WHERE v.match_id=m.id AND v.status='confirmed')",event);n.put("matches",matches);n.put("missingResults",unsettled);n.put("proofsAwaitingReview",proofReviewCount(event));
 long obligations=db.count("SELECT count(*) FROM asp_fee_obligation f JOIN asp_registration r ON r.id=f.registration_id JOIN asp_competition_unit u ON u.id=r.unit_id WHERE u.event_id=? AND f.status='open'",event);long actions=db.count("SELECT count(*) FROM asp_payment_action pa JOIN asp_fee_obligation f ON f.id=pa.obligation_id JOIN asp_registration r ON r.id=f.registration_id JOIN asp_competition_unit u ON u.id=r.unit_id WHERE u.event_id=? AND pa.status='pending'",event);long exceptions=db.count("SELECT count(DISTINCT x.id) FROM asp_payment_exception x LEFT JOIN asp_fee_obligation f ON f.id=x.obligation_id LEFT JOIN asp_payment_allocation a ON a.payment_id=x.payment_id LEFT JOIN asp_fee_obligation f2 ON f2.id=a.obligation_id JOIN asp_registration r ON r.id=COALESCE(f.registration_id,f2.registration_id) JOIN asp_competition_unit u ON u.id=r.unit_id WHERE u.event_id=? AND x.status<>'resolved'",event);long refunds=db.count("SELECT count(DISTINCT rf.id) FROM asp_refund rf JOIN asp_payment_allocation a ON a.payment_id=rf.payment_id JOIN asp_fee_obligation f ON f.id=a.obligation_id JOIN asp_registration r ON r.id=f.registration_id JOIN asp_competition_unit u ON u.id=r.unit_id WHERE u.event_id=? AND rf.status NOT IN('completed','rejected')",event);n.put("openObligations",obligations);n.put("pendingFundActions",actions);n.put("unresolvedPaymentExceptions",exceptions);n.put("pendingRefunds",refunds);n.put("fundsClosed",obligations+actions+exceptions+refunds==0);
 long issues=db.count("SELECT count(*) FROM asp_complaint c WHERE c.status NOT IN('resolved','rejected') AND ((c.object_type='event' AND c.object_id=?) OR(c.object_type='registration' AND c.object_id IN(SELECT r.id FROM asp_registration r JOIN asp_competition_unit u ON u.id=r.unit_id WHERE u.event_id=?)))",event,event);n.put("openIssues",issues);n.put("issuesClosed",issues==0);n.put("competitionEnded",e.get("holding_status").equals("cancelled")||(Boolean.TRUE.equals(e.get("has_started"))&&!e.get("closure_status").equals("open")));return n;}
 public JsonNode execute(String code,JsonNode in){long event=id(in,"eventId");if(code.equals("event.closure"))return summary(event);if(TrustedRunContext.current()!=null)throw fail("赛后收尾须由责任人核实",403);db.lock("event-closure:"+event);var s=summary(event);if(s.path("event").path("version").asInt()!=in.path("expectedVersion").asInt(-1))throw fail("赛事状态已变化，请刷新",409);
 // Cancellation has its own refund/complaint responsibilities and may close before the planned start.
 if(!s.path("event").path("holding_status").asText().equals("cancelled")&&!s.path("event").path("has_started").asBoolean())throw fail("赛事尚未开赛，不能确认比赛结束或完成赛后收尾",409);
 if(code.equals("event.wrapup")){if(!s.path("event").path("holding_status").asText().equals("cancelled")&&(s.path("matches").asLong()==0||s.path("missingResults").asLong()>0))throw fail("请先确认各场次正式结果，或办理赛事取消",409);db.update("UPDATE asp_event SET closure_status='wrap_up',registration_closes_at=LEAST(registration_closes_at,CURRENT_TIMESTAMP),version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",event);return reference(json,"eventId",event,"wrap_up");}
 if(!s.path("competitionEnded").asBoolean()||!s.path("fundsClosed").asBoolean()||!s.path("issuesClosed").asBoolean()||s.path("proofsAwaitingReview").asLong()>0)throw fail("比赛、资金、问题或证明仍有待办，请逐项处理",409);db.update("UPDATE asp_event SET closure_status='closed',version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",event);return reference(json,"eventId",event,"closed");}
 private long proofReviewCount(long event){
  List<EventAwardLineage.Claim> claims=new ArrayList<>();
  for(var h:db.list("SELECT id,registration_id,person_id,award_key,title,status,source::text AS source_text FROM asp_honor WHERE event_id=? AND category='event' AND award_key IS NOT NULL",event))try{claims.add(new EventAwardLineage.Claim(number(h.get("id")),number(h.get("registration_id")),number(h.get("person_id")),h.get("award_key").toString(),h.get("title").toString(),json.readTree(h.get("source_text").toString()),h.get("status").toString()));}catch(Exception e){throw fail("获奖依据无法读取，请先核对",409);}
  return EventAwardLineage.latest(claims).stream().filter(c->Set.of("pending","suspended","revised").contains(c.status())).map(c->EventAwardLineage.key(c,claims)).distinct().count();
 }

}

